public void run()
{

    SalesTable salesTableLocal = this.salesTable();

    CustVendorBlocked   blockStatus   = CustTable::find(salesTableLocal.CustAccount).Blocked;

    // Verify if the CustAccount is blocked post sales invoice should not trigger
    if (blockStatus == CustVendorBlocked::METSalesinvoice)
    {
        throw warning(strFmt("@SYS18389", salesTableLocal.CustAccount, enum2Str(blockStatus)));
    }

    next run();

    if (salesTableLocal.ReturnItemNum)
    {
        SalesLine salesLine;

        while select salesLine
            where salesLine.SalesId == salesTableLocal.SalesId
        {
            SalesFormLetter_Invoice::applyCWClaimCredit(salesLine);
        }
    }

}

/// <summary>
/// Applies Catch Weight (CW) credit logic to a return sales line during invoicing.
/// Calculates credit based on CW return weight if the disposition code and item setup meet the criteria.
/// </summary>
/// <param name="_salesLine">The return order sales line being invoiced</param>
public static void applyCWClaimCredit(SalesLine _salesLine)
{
    METCustParameters arParams = METCustParameters::find();

    // Get the CW return weight from the extended sales line
    METCWReturnWeight cwReturnWeight = _salesLine.metSalesLine().CWReturnWeight;

    // Get the original RMA sales line using InventTransIdReturn
    SalesLine rmaSalesLine = SalesLine::find(_salesLine.InventTransIdReturn);

    // Validate business rules:
    // - Disposition code must match configured CW claim code
    // - CW return weight must be provided
    if (rmaSalesLine.ReturnDispositionCodeId != arParams.CWClaimDispositionCodeId || !cwReturnWeight)
    {
        return;
    }

    //  Validate item setup:
    // - Item must be catch weight enabled
    InventTable inventTable = InventTable::find(_salesLine.ItemId);

    if (!inventTable || !inventTable.pdsCWItem())
    {
        return;
    }

    // 🔹 Retrieve and update price components based on CW return weight
    METSalesLinePriceComponentTmp priceComponent;

    while select forUpdate priceComponent
        where priceComponent.InventTransId == _salesLine.InventTransId
    {
        // 🔸 Calculate extended value for each price component
        priceComponent.ExtValue = priceComponent.Value * cwReturnWeight;
        priceComponent.update();

        // 🔸 If component is base price, update the sales line's net amount
        if (priceComponent.PriceComponent == METPriceComponent::BasePrice)
        {
            _salesLine.LineAmount = priceComponent.ExtValue;
            _salesLine.update();
        }
    }
}
